-- Generated by Supabase CLI 2.120.0 migration new, then placed in this repo's SQL directory.
-- Dependencies: migration 59 (canonical actor/amount boundary). No historical backfill.
BEGIN;

CREATE TABLE public.order_payment_commands (
    command_id uuid PRIMARY KEY,
    order_id uuid NOT NULL REFERENCES public.pedidos(id) ON DELETE RESTRICT,
    actor_id uuid NOT NULL,
    payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
    result jsonb NOT NULL CHECK (jsonb_typeof(result) = 'object'),
    completed_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX order_payment_commands_order_idx ON public.order_payment_commands(order_id);
ALTER TABLE public.order_payment_commands ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.order_payment_commands FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.order_payment_commands TO service_role;

CREATE OR REPLACE FUNCTION public.prevent_order_payment_command_mutation()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public
AS $$
BEGIN
    RAISE EXCEPTION 'PAYMENT_COMMAND_IMMUTABLE';
END;
$$;
REVOKE ALL ON FUNCTION public.prevent_order_payment_command_mutation() FROM PUBLIC;
CREATE TRIGGER order_payment_commands_immutable
BEFORE UPDATE OR DELETE ON public.order_payment_commands
FOR EACH ROW EXECUTE FUNCTION public.prevent_order_payment_command_mutation();

CREATE OR REPLACE FUNCTION public.confirm_order_payment_command(
    p_command_id uuid, p_order_id uuid, p_target_status text,
    p_payments jsonb, p_actor_id uuid DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_actor uuid := auth.uid();
    v_count bigint;
    v_role text;
    v_hash text;
    v_existing public.order_payment_commands%ROWTYPE;
    v_status text;
    v_result jsonb;
BEGIN
    IF v_actor IS NULL OR (p_actor_id IS NOT NULL AND p_actor_id <> v_actor) THEN
        RAISE EXCEPTION 'PAYMENT_ACTOR_UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;
    SELECT count(*), max(lower(btrim(s.rol))) INTO v_count, v_role
    FROM public.socios AS s WHERE s.auth_user_id = v_actor;
    IF v_count <> 1 OR v_role IS NULL OR v_role NOT IN ('admin', 'staff') THEN
        RAISE EXCEPTION 'PAYMENT_ROLE_UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;
    IF p_command_id IS NULL OR p_order_id IS NULL
       OR p_target_status IS NULL OR p_target_status NOT IN ('entregado', 'retirado') THEN
        RAISE EXCEPTION 'PAYMENT_COMMAND_INVALID' USING ERRCODE = '22023';
    END IF;
    IF p_payments IS NULL OR jsonb_typeof(p_payments) <> 'array' THEN
        RAISE EXCEPTION 'PAYMENT_PAYLOAD_INVALID' USING ERRCODE = '22023';
    END IF;
    IF jsonb_array_length(p_payments) = 0 THEN
        RAISE EXCEPTION 'PAYMENT_PAYLOAD_INVALID' USING ERRCODE = '22023';
    END IF;
    v_hash := encode(sha256(convert_to(jsonb_build_object(
        'order_id', p_order_id, 'actor_id', v_actor,
        'target_status', p_target_status, 'payments', p_payments
    )::text, 'UTF8')), 'hex');

    -- One command lock, then one order lock: same-key retries serialize before business writes.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_command_id::text, 0));
    SELECT * INTO v_existing FROM public.order_payment_commands AS c
    WHERE c.command_id = p_command_id;
    IF FOUND THEN
        IF v_existing.actor_id <> v_actor OR v_existing.order_id <> p_order_id
           OR v_existing.payload_hash <> v_hash THEN
            RAISE EXCEPTION 'PAYMENT_COMMAND_CONFLICT' USING ERRCODE = '22023';
        END IF;
        RETURN v_existing.result || jsonb_build_object('command_id', p_command_id, 'reused', true);
    END IF;

    SELECT p.estado INTO v_status FROM public.pedidos AS p
    WHERE p.id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'PAYMENT_ORDER_NOT_FOUND';
    END IF;
    IF v_status IN ('entregado', 'retirado', 'cancelado') THEN
        RAISE EXCEPTION 'PAYMENT_ORDER_ALREADY_FINALIZED';
    END IF;
    v_result := public.confirm_order_and_payments(p_order_id, p_target_status, p_payments, v_actor);
    IF v_result->>'success' IS DISTINCT FROM 'true' THEN
        RAISE EXCEPTION 'PAYMENT_CONFIRMATION_FAILED';
    END IF;
    INSERT INTO public.order_payment_commands(command_id, order_id, actor_id, payload_hash, result)
    VALUES (p_command_id, p_order_id, v_actor, v_hash, v_result);
    RETURN v_result || jsonb_build_object('command_id', p_command_id, 'reused', false);
END;
$$;
REVOKE ALL ON FUNCTION public.confirm_order_payment_command(uuid,uuid,text,jsonb,uuid)
FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION public.confirm_order_payment_command(uuid,uuid,text,jsonb,uuid)
TO authenticated;
-- The legacy implementation remains internal to the command; never expose a keyless bypass.
REVOKE ALL ON FUNCTION public.confirm_order_and_payments(uuid,text,jsonb,uuid)
FROM PUBLIC, anon, authenticated, service_role;
COMMIT;
